nta.declaration:
// ============================================================================
// DWTA realtime C2 pipeline -- v6 (FULL: Planner-as-decider + Salvo + Pk + jitter)
// ----------------------------------------------------------------------------
//  Single canonical model uniting every axis from the mission-procedure diagram:
//
//    [process]       Planner owns the WTA decision (mirrors ROS2's
//                    planning_node._tick -> GreedyWTA.solve() -> Assignment list).
//                    Handshake assign_u[b][t] / assign_l[b][t] channels make
//                    the (battery, threat) decision explicit per ROS2's
//                    LauncherNode._on_plan dispatch.
//
//    [multi-layer]   Upper (L-SAM) + Lower (M-SAM) layers with independent
//                    Slot_U / Slot_L pools.  Same threat may be covered by
//                    both layers (R4 reachability query).
//
//    [per-battery]   CH_PER_U[b] / CH_PER_L[b] -- each battery owns a
//                    distinct channel pool.  Slot instances are per channel.
//
//    [Pk]            PK_U[t][b] / PK_L[t][b] (Pk * 100) attached to hit/miss
//                    edges as probability weights -- becomes a Bernoulli
//                    branch under SMC, stays as a free nondeterministic
//                    choice under classical TCTL (both safe).
//
//    [salvo]         MAX_SALVO_U / MAX_SALVO_L concurrent shots per
//                    (battery, threat).  Encoded via best_u_b_salvo's
//                    "upCnt_bt[b][i] less than MAX_SALVO_U" gate and the
//                    Planner's salvo_step counter inside Decide.
//
//    [range+altitude] (range AND altitude) intersection precomputed per
//                    (threat, battery) into U_ENTER/U_EXIT/L_ENTER/L_EXIT
//                    time windows.  Radar broadcasts enter/exit at the right
//                    instants; Threat toggles engU_b[t][b] / engL_b[t][b].
//
//    [flyout jitter] FLYOUT_U_MIN..MAX (and L variant): missile spends a
//                    nondeterministic time inside the window before its
//                    hit/miss verdict fires.
//
//  Scenario constants between the BEGIN / END AUTO-GENERATED markers are
//  produced by ros2_dwta.dwta_nodes.scenario.dump_uppaal_windows() and
//  injected with inject_uppaal_constants().  Everything else is the model
//  structure and stays stable across scenarios.
// ============================================================================

// ---- model structure (stable) ---------------------------------------------
const int MAXT             = 3;
const int NB_U             = 2;
const int NB_L             = 2;
const int CH_PER_U[NB_U]   = {3, 2};
const int CH_PER_L[NB_L]   = {3, 2};
const int FLYOUT_U_MIN     = 4;
const int FLYOUT_U_MAX     = 6;
const int FLYOUT_L_MIN     = 1;
const int FLYOUT_L_MAX     = 3;
const int PERIOD_P         = 2;
const int MAX_SALVO_U      = 2;
const int MAX_SALVO_L      = 1;

// ===== BEGIN AUTO-GENERATED SCENARIO CONSTS =====
// Replace this block with the output of:
//   python -c "import sys; sys.path.insert(0,'ros2_dwta'); \
//     from dwta_nodes.scenario import dump_uppaal_scenario; \
//     print(dump_uppaal_scenario(seed=42, n_threats=3))"
// or call inject_uppaal_constants() to overwrite in place.
const int APPEAR[MAXT]        = { 0,  3,  6};
const int IMPACT_AT[MAXT]     = {30, 32, 35};
const int U_ENTER[MAXT][NB_U] = { { 8, 9}, {11,12}, {14,15} };
const int U_EXIT [MAXT][NB_U] = { {22,21}, {24,23}, {26,25} };
const int L_ENTER[MAXT][NB_L] = { {16,17}, {19,18}, {20,21} };
const int L_EXIT [MAXT][NB_L] = { {28,27}, {30,29}, {33,31} };
const int PK_U[MAXT][NB_U]    = { {85,80}, {78,82}, {88,75} };
const int PK_L[MAXT][NB_L]    = { {72,70}, {75,73}, {68,71} };
// ===== END AUTO-GENERATED SCENARIO CONSTS =====

// ---- shared state ----------------------------------------------------------
int  ammoU_b[NB_U]    = {4, 3};
int  ammoL_b[NB_L]    = {4, 3};
int  inflU_b[NB_U];
int  inflL_b[NB_L];
int  upCnt_bt[NB_U][MAXT];
int  loCnt_bt[NB_L][MAXT];
bool engU_b[MAXT][NB_U];
bool engL_b[MAXT][NB_L];
int  killed = 0, leaked = 0;
int  shots_u_fired = 0;
int  shots_l_fired = 0;

// ---- channels --------------------------------------------------------------
// Handshake: exactly one Idle Slot of (batt_id) matches each assign! fire.
chan assign_u[NB_U][MAXT];
chan assign_l[NB_L][MAXT];
// Broadcast: 0+ receivers OK (terminal threats ignore late hit/miss).
broadcast chan detect[MAXT];
broadcast chan impact[MAXT];
broadcast chan enterU0[MAXT], exitU0[MAXT];
broadcast chan enterU1[MAXT], exitU1[MAXT];
broadcast chan enterL0[MAXT], exitL0[MAXT];
broadcast chan enterL1[MAXT], exitL1[MAXT];
broadcast chan hitU[MAXT], missU[MAXT];
broadcast chan hitL[MAXT], missL[MAXT];

// ---- salvo-aware GreedyWTA priority ----------------------------------------
int best_u_b_salvo(int b) {
    int i = 0;
    while (i < MAXT) {
        if (engU_b[i][b] && upCnt_bt[b][i] < MAX_SALVO_U) return i;
        i++;
    }
    return -1;
}
int best_l_b_salvo(int b) {
    int i = 0;
    while (i < MAXT) {
        if (engL_b[i][b] && loCnt_bt[b][i] < MAX_SALVO_L) return i;
        i++;
    }
    return -1;
}
bool any_uCover(int t) { return upCnt_bt[0][t] + upCnt_bt[1][t] > 0; }
bool any_lCover(int t) { return loCnt_bt[0][t] + loCnt_bt[1][t] > 0; }

nta.system:
R0 = Radar(0); R1 = Radar(1); R2 = Radar(2);
T0 = Threat(0); T1 = Threat(1); T2 = Threat(2);
// Upper: CH_PER_U = {3, 2}
SU0_0 = Slot_U(0); SU0_1 = Slot_U(0); SU0_2 = Slot_U(0);
SU1_0 = Slot_U(1); SU1_1 = Slot_U(1);
// Lower: CH_PER_L = {3, 2}
SL0_0 = Slot_L(0); SL0_1 = Slot_L(0); SL0_2 = Slot_L(0);
SL1_0 = Slot_L(1); SL1_1 = Slot_L(1);
P = Planner();
system R0, R1, R2, T0, T1, T2,
       SU0_0, SU0_1, SU0_2, SU1_0, SU1_1,
       SL0_0, SL0_1, SL0_2, SL1_0, SL1_1,
       P;
